// Regenerates supabase/ALL_MIGRATIONS.sql from supabase/migrations/, for a
// single paste into the Supabase SQL Editor. Run after adding a migration.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = "supabase/migrations";
const out = "supabase/ALL_MIGRATIONS.sql";

const header = `-- ============================================================================
-- D|R|P PMS - all migrations, concatenated for a single paste into the
-- Supabase SQL Editor.
--
-- Generated from supabase/migrations/ - do not edit this file; edit the
-- individual migrations and run \`npm run db:concat\`.
--
-- Run ONCE against a fresh Supabase project. It is not idempotent: re-running
-- it on a database that already has the schema will fail on the first
-- CREATE TYPE. To start over, run \`drop schema public cascade; create schema
-- public;\` first (this destroys all data).
--
-- Do NOT run supabase/local/00_shim.sql against Supabase - auth.users,
-- auth.uid() and storage.* already exist there.
-- ============================================================================

`;

const rule = "-- " + "#".repeat(68);
const files = readdirSync(dir).filter((f) => /^\d+_.*\.sql$/.test(f)).sort();
const body = files
  .map((f) => {
    const sql = readFileSync(`${dir}/${f}`, "utf8").replace(/\r\n/g, "\n");
    return `\n${rule}\n-- ## ${f}\n${rule}\n\n${sql.endsWith("\n") ? sql : sql + "\n"}`;
  })
  .join("");

writeFileSync(out, header + body);
console.log(`${out}: ${files.length} migrations`);
